<?php// app/Models/Succursale.phpnamespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;use App\Traits\Auditable;class Succursale extends Model{    use HasFactory, SoftDeletes, Auditable;    protected $table = 'succursales';    protected $fillable = [        'code',        'nom',        'type',        'telephone',        'email',        'responsable_id',        'adresse',        'ville',        'province',        'pays',        'code_postal',        'coordonnees_gps',        'heure_ouverture',        'heure_fermeture',        'est_principale',        'configuration',        'jours_ouverture',        'capacite_maximale',        'nombre_employes',        'zone_geo',        'statut',        'entite_id',        'est_active',        'date_activation',        'date_desactivation',        'motif_desactivation',        'metadata'    ];    protected $casts = [        'coordonnees_gps' => 'array',        'est_principale' => 'boolean',        'configuration' => 'array',        'jours_ouverture' => 'array',        'capacite_maximale' => 'integer',        'nombre_employes' => 'integer',        'est_active' => 'boolean',        'date_activation' => 'datetime',        'date_desactivation' => 'datetime',        'metadata' => 'array'    ];    protected $attributes = [        'pays' => 'RDC',        'est_active' => true,        'statut' => 'ACTIVE'    ];    protected static function boot()    {        parent::boot();        static::creating(function ($succursale) {            if (empty($succursale->code)) {                $succursale->code = static::genererCode($succursale->nom);            }        });        static::created(function ($succursale) {            $succursale->logAudit('CREATION', null, $succursale->toArray());            // Si un responsable a été assigné, mettre à jour sa succursale_id            if ($succursale->responsable_id) {                $responsable = Utilisateur::find($succursale->responsable_id);                if ($responsable && !$responsable->succursale_id) {                    $responsable->succursale_id = $succursale->id;                    $responsable->save();                }            }        });        static::updated(function ($succursale) {            $changes = $succursale->getChanges();            $original = [];            foreach (array_keys($changes) as $key) {                $original[$key] = $succursale->getOriginal($key);            }            $succursale->logAudit('MODIFICATION', $original, $changes);            // Si le responsable_id a changé, mettre à jour les relations            if (isset($changes['responsable_id'])) {                // Ancien responsable                if (isset($original['responsable_id']) && $original['responsable_id']) {                    $ancienResponsable = Utilisateur::find($original['responsable_id']);                    if ($ancienResponsable && $ancienResponsable->succursale_id == $succursale->id) {                        $ancienResponsable->succursale_id = null;                        $ancienResponsable->save();                    }                }                // Nouveau responsable                if (isset($changes['responsable_id']) && $changes['responsable_id']) {                    $nouveauResponsable = Utilisateur::find($changes['responsable_id']);                    if ($nouveauResponsable) {                        $nouveauResponsable->succursale_id = $succursale->id;                        $nouveauResponsable->save();                    }                }            }        });        static::deleting(function ($succursale) {            if ($succursale->utilisateurs()->count() > 0) {                throw new \Exception('Impossible de supprimer une succursale avec des utilisateurs actifs');            }            if ($succursale->caisses()->where('statut', 'OUVERTE')->count() > 0) {                throw new \Exception('Fermez d\'abord toutes les caisses ouvertes');            }            // Retirer le responsable si présent            if ($succursale->responsable_id) {                $responsable = Utilisateur::find($succursale->responsable_id);                if ($responsable && $responsable->succursale_id == $succursale->id) {                    $responsable->succursale_id = null;                    $responsable->save();                }            }        });    }    public static function genererCode($nom)    {        $prefix = 'SUC';        $nomCode = strtoupper(substr(preg_replace('/[^A-Za-z0-9]/', '', $nom), 0, 3));        $count = static::withTrashed()->count() + 1;        return "{$prefix}{$nomCode}" . str_pad($count, 3, '0', STR_PAD_LEFT);    }    /**     * Relation avec le responsable (utilisateur)     */    public function responsable()    {        return $this->belongsTo(Utilisateur::class, 'responsable_id')            ->select(['id', 'nom_complet', 'email', 'telephone', 'matricule', 'role_id']);    }        public function entite()	{		return $this->belongsTo(Entite::class);	}	public function ecritures_comptables()	{		return $this->hasMany(EcrituresComptable::class);	}    public function utilisateurs()    {        return $this->hasMany(Utilisateur::class, 'succursale_id');    }    public function caisses()    {        return $this->hasMany(Caisses::class, 'succursale_id');    }    public function clients()    {        return $this->hasMany(Client::class, 'succursale_id');    }    public function factures()    {        return $this->hasMany(Facture::class, 'succursale_id');    }            public function fraisLivraisons()    {        return $this->hasMany(FraisLivraison::class);    }    public function getNombreUtilisateursActifsAttribute()    {        return $this->utilisateurs()            ->where('statut', 'ACTIF')            ->where('compte_verrouille', false)            ->count();    }    public function getNombreCaissesOuvertesAttribute()    {        return $this->caisses()            ->where('statut', 'OUVERTE')            ->count();    }    public function getSoldeTotalCaissesAttribute()    {        return $this->caisses()            ->where('statut', 'OUVERTE');            // ->sum('solde');    }        /**     * Relation avec les commandes clients     */    public function commandes()    {        return $this->hasMany(CommandeClient::class, 'succursale_assignee_id');    }    /**     * Relation avec les commandes clients assignées     */    public function commandesAssignees()    {        return $this->hasMany(CommandeClient::class, 'succursale_assignee_id');    }        // Dans le modèle Succursale    public function commandesEnCours()    {        return $this->hasMany(CommandeClient::class, 'succursale_assignee_id')            ->whereIn('statut', ['ASSIGNEE', 'EN_PREPARATION', 'PRETE', 'EN_LIVRAISON']);    }    public function getEstOuverteMaintenantAttribute()    {        if (!$this->heure_ouverture || !$this->heure_fermeture) {            return true;        }        $now = now();        $jour = strtolower($now->format('l'));        $joursOuverture = $this->jours_ouverture;        if (is_string($joursOuverture)) {            $joursOuverture = json_decode($joursOuverture, true) ?? [];        }        if (!empty($joursOuverture) && !in_array($jour, $joursOuverture)) {            return false;        }        $heure = $now->format('H:i:s');        return $heure >= $this->heure_ouverture && $heure <= $this->heure_fermeture;    }    /**     * Vérifier si un utilisateur peut être responsable de cette succursale     */    public function peutEtreResponsable(Utilisateur $utilisateur): bool    {        // Vérifier le rôle        $rolesResponsable = ['CHEF_AGENCE', 'SUPERVISEUR', 'SUPER_ADMIN'];        if (!in_array($utilisateur->role?->code, $rolesResponsable)) {            return false;        }        // Vérifier qu'il n'est pas déjà responsable d'une autre succursale        if ($utilisateur->succursale_id && $utilisateur->succursale_id != $this->id) {            $autreSuccursale = Succursale::where('responsable_id', $utilisateur->id)                ->where('id', '!=', $this->id)                ->exists();            if ($autreSuccursale) {                return false;            }        }        return true;    }    public function desactiver($motif = null)    {        // 1. Désactiver la succursale        $this->update([            'est_active' => false,            'statut' => 'INACTIVE',            'date_desactivation' => now(),            'motif_desactivation' => $motif        ]);        $this->utilisateurs()            ->whereNotIn('role_id', function($query) {                $query->select('id')                    ->from('roles')                    ->whereIn('code', ['SUPER_ADMIN', 'CHEF_OPERATIONS', 'CHEF_AGENCE']);            })            ->update(['statut' => 'INACTIF']);        // 3. Log d'audit        $this->logAudit('DESACTIVATION', null, [            'motif' => $motif,            'succursale_id' => $this->id,            'succursale_nom' => $this->nom,            'utilisateurs_conserves' => $this->utilisateurs()                ->whereIn('role_id', function($query) {                    $query->select('id')                        ->from('roles')                        ->whereIn('code', ['SUPER_ADMIN', 'CHEF_OPERATIONS', 'CHEF_AGENCE']);                })                ->pluck('id')                ->toArray(),            'utilisateurs_desactives' => $this->utilisateurs()                ->whereNotIn('role_id', function($query) {                    $query->select('id')                        ->from('roles')                        ->whereIn('code', ['SUPER_ADMIN', 'CHEF_OPERATIONS', 'CHEF_AGENCE']);                })                ->pluck('id')                ->toArray()        ]);        return $this;    }    public function activer()    {        // 1. Réactiver la succursale        $this->update([            'est_active' => true,            'statut' => 'ACTIVE',            'date_activation' => now(),            'date_desactivation' => null,            'motif_desactivation' => null        ]);        $this->utilisateurs()->update(['statut' => 'ACTIF']);        // 3. Log d'audit        $this->logAudit('ACTIVATION', null, [            'succursale_id' => $this->id,            'succursale_nom' => $this->nom,            'utilisateurs_reactives' => $this->utilisateurs()->pluck('id')->toArray()        ]);        return $this;    }    public function mettreEnMaintenance($motif = null)    {        $this->update([            'statut' => 'MAINTENANCE',            'metadata' => array_merge($this->metadata ?? [], [                'maintenance_debut' => now(),                'maintenance_motif' => $motif            ])        ]);        $this->logAudit('MAINTENANCE', null, ['motif' => $motif]);    }    // ============================================================    // MÉTHODES DE GESTION DE STOCK    // ============================================================    public function getOrCreateStock($produitId, $isDepot = false, $raison = null)    {        $stock = StockSuccursale::where('succursale_id', $this->id)            ->where('produit_id', $produitId)            ->first();        if (!$stock) {            $produit = Produit::find($produitId);            $stock = StockSuccursale::create([                'succursale_id' => $this->id,                'produit_id' => $produitId,                'quantite_disponible' => 0,                'quantite_reserve' => 0,                'quantite_minimale' => $produit->stock_minimum ?? 5,                'is_depot' => $isDepot,                'emplacement' => 'Créé automatiquement',                'created_at' => now(),                'updated_at' => now()            ]);        }        return $stock;    }    public function ajouterStock($produitId, $quantite, $isDepot = false, $raison = null){    $stock = StockSuccursale::where('succursale_id', $this->id)        ->where('produit_id', $produitId)        ->first();    if (!$stock) {        $produit = Produit::find($produitId);        $stock = StockSuccursale::create([            'succursale_id' => $this->id,            'produit_id' => $produitId,            'quantite_disponible' => 0,            'quantite_reserve' => 0,            'quantite_minimale' => $produit->stock_minimum ?? 5,            'is_depot' => $isDepot,            'emplacement' => 'Créé automatiquement'        ]);    }    $stock->ajouterStock($quantite, 'ENTREE', $raison);    return $stock;}    public function retirerStock($produitId, $quantite, $raison = null)    {        $stock = StockSuccursale::where('succursale_id', $this->id)            ->where('produit_id', $produitId)            ->first();        if (!$stock) {            throw new \Exception("Stock non trouvé pour le produit ID {$produitId} dans cette succursale");        }        $stock->diminuerStock($quantite, 'SORTIE', $raison);        return $stock;    }    public function getStock($produitId)    {        return StockSuccursale::where('succursale_id', $this->id)            ->where('produit_id', $produitId)            ->first();    }    public function aStockSuffisant($produitId, $quantiteNecessaire)    {        $stock = $this->getStock($produitId);        return $stock && $stock->quantite_disponible >= $quantiteNecessaire;    }            public function fraisLivraison($id)    {        $succursale = Succursale::findOrFail($id);            return response()->json([            'success' => true,            'data' => $succursale->fraisLivraisons()                ->with('devise')                ->where('actif', true)                ->get()        ]);    }    public function scopeActives($query)    {        return $query->where('est_active', true)            ->where('statut', 'ACTIVE');    }    public function scopePrincipales($query)    {        return $query->where('est_principale', true);    }    public function scopeAvecResponsable($query)    {        return $query->whereNotNull('responsable_id');    }    public function scopeSansResponsable($query)    {        return $query->whereNull('responsable_id');    }    public function scopeParVille($query, $ville)    {        return $query->where('ville', $ville);    }    public function scopeParZone($query, $zone)    {        return $query->where('zone_geo', $zone);    }    public function toArray()    {        $array = parent::toArray();        $array['nombre_utilisateurs_actifs'] = $this->nombre_utilisateurs_actifs;        $array['nombre_caisses_ouvertes'] = $this->nombre_caisses_ouvertes;        // $array['solde_total_caisses'] = $this->solde_total_caisses;        $array['est_ouverte_maintenant'] = $this->est_ouverte_maintenant;        // Ajouter des infos supplémentaires sur le responsable si chargé        if ($this->relationLoaded('responsable') && $this->responsable) {            $array['responsable_nom'] = $this->responsable->nom_complet;            $array['responsable_matricule'] = $this->responsable->matricule;            $array['responsable_role'] = $this->responsable->role?->nom_role;            $array['responsable_email'] = $this->responsable->email;        }        return $array;    }        public function resultats()    {        return $this->hasMany(Resultat::class, 'succursale_id');    }        // Dans la classe PeriodesComptable, ajouter cette méthode :    public function tvaComptables()    {        return $this->hasMany(TvaComptable::class, 'periode_id');    }}